INSERT INTO `activities` VALUES (1,1,'Breath Awareness Meditation','Learn to anchor your attention in the present moment using your breath as a focal point.','Meditation',5,10,NULL,1,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"What is Breath Awareness?\", \"content\": \"Breath awareness is the foundation of mindfulness practice. By focusing on your natural breathing, you train your mind to stay present and develop the ability to notice when your attention wanders.\"}, {\"list\": [\"Find a comfortable seated position with your back straight\", \"Close your eyes gently or lower your gaze\", \"Take three deep breaths to settle in\", \"Let your breathing return to its natural rhythm\", \"Notice the sensation of air entering your nostrils\", \"Feel your chest and belly expand with each inhale\", \"Notice the brief pause at the top of the breath\", \"Feel the air leaving as you exhale\", \"When your mind wanders, gently return focus to the breath\", \"Continue for the full 5 minutes\"], \"title\": \"Instructions\"}, {\"list\": [\"Reduces stress and anxiety quickly\", \"Improves focus and concentration\", \"Calms the nervous system naturally\", \"Easy to practice anywhere, anytime\"], \"title\": \"Benefits\"}], \"description\": \"Learn to anchor your attention in the present moment using your breath as a focal point.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/inpok4MKVLM'),(2,1,'Extended Breath-Focused Practice','Extended breath-focused practice teaching proper meditation posture and breath observation.','Meditation',10,25,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"About This Practice\", \"content\": \"This 10-minute practice builds on basic breath awareness by introducing sustained attention and proper posture. You will develop the ability to maintain focus for longer periods while staying relaxed and comfortable.\"}, {\"list\": [\"Sit with your spine upright but not rigid\", \"Rest your hands comfortably on your knees or lap\", \"Close your eyes and take three deep breaths\", \"Allow your breathing to become natural and easy\", \"Focus on the cool air entering your nostrils\", \"Notice the warm air leaving your nostrils\", \"Count your breaths from 1 to 10, then start over\", \"If you lose count, simply start again at 1\", \"Notice the space between inhale and exhale\", \"When thoughts arise, acknowledge them and return to breath\", \"Gradually deepen your attention over the 10 minutes\", \"End with three intentional deep breaths\"], \"title\": \"Instructions\"}, {\"list\": [\"Develops sustained concentration ability\", \"Trains the mind to notice distractions\", \"Creates mental clarity and calmness\", \"Strengthens mindfulness capacity\"], \"title\": \"Benefits\"}], \"description\": \"Extended breath-focused practice teaching proper meditation posture and deeper breath observation.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/thcEuMDWxoI'),(3,1,'Mindful Breathing Variations','Learn to use multiple anchor points (nostrils, chest, belly) to deepen breath awareness.','Breathing',15,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"?️\", \"sections\": [{\"title\": \"About Breath Anchoring\", \"content\": \"Different parts of your breathing experience can serve as anchors for your attention. By exploring multiple anchor points, you develop flexibility in meditation and discover which works best for you.\"}, {\"list\": [\"Begin seated comfortably with eyes closed\", \"Start with 5 breaths focusing on your nostrils\", \"Notice the temperature and sensation of air\", \"Shift attention to your chest for 5 breaths\", \"Feel the rise and fall of your rib cage\", \"Move awareness to your belly for 5 breaths\", \"Notice the gentle expansion and contraction\", \"Practice moving between all three anchor points\", \"Spend 2 minutes with each anchor point\", \"Notice which anchor point feels most stable\", \"Return to your preferred anchor for the final 3 minutes\", \"End by taking three complete deep breaths\"], \"title\": \"Instructions\"}, {\"list\": [\"Develops flexibility in meditation practice\", \"Helps find your personal best anchor point\", \"Deepens body awareness significantly\", \"Improves ability to redirect wandering attention\"], \"title\": \"Benefits\"}], \"description\": \"Learn to use multiple anchor points (nostrils, chest, belly) to deepen breath awareness.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/wfDTp2GogaQ'),(4,1,'Body Scan Meditation','Systematically move attention through your body, noticing sensations without judgment.','Body Scan',20,50,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"What is Body Scan Meditation?\", \"content\": \"Body scan is a practice where you systematically move your attention through different parts of your body. This builds interoceptive awareness - your ability to sense what is happening inside your body - and releases accumulated tension.\"}, {\"list\": [\"Lie down on your back or sit comfortably\", \"Close your eyes and take three deep breaths\", \"Bring attention to the top of your head\", \"Notice any sensations - warmth, tingling, tension\", \"Slowly move awareness to your forehead and eyes\", \"Continue to your jaw, noticing if you are clenching\", \"Scan through your neck and shoulders\", \"Move down through arms, hands, and fingers\", \"Bring awareness to your chest and upper back\", \"Scan your belly, lower back, and hips\", \"Continue through thighs, knees, calves, and feet\", \"Finish by feeling your whole body at once\", \"Take three final deep breaths before opening eyes\"], \"title\": \"Instructions\"}, {\"list\": [\"Releases physical tension you did not know you held\", \"Improves mind-body connection deeply\", \"Helps with relaxation and better sleep\", \"Increases overall body awareness\", \"Reduces chronic pain and stress\"], \"title\": \"Benefits\"}], \"description\": \"Systematically move attention through your body, noticing sensations without judgment.\", \"timerMinutes\": 20}','video','https://www.youtube.com/embed/15q-N-_kkrU'),(5,1,'Integrative Mindfulness Practice','Combine breath awareness, body scanning, and present-moment anchoring.','Meditation',30,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"About Integrative Practice\", \"content\": \"This 30-minute session brings together all the foundational techniques you have learned. You will flow between breath awareness, body scanning, and open awareness, developing a complete mindfulness practice.\"}, {\"list\": [\"Settle into a comfortable meditation posture\", \"Begin with 5 minutes of breath awareness\", \"Use your nostrils as the primary anchor point\", \"Transition to a 10-minute body scan\", \"Move slowly from head to toes with gentle attention\", \"Return to breath awareness for 5 minutes\", \"Now practice open awareness for 5 minutes\", \"Notice sounds, thoughts, and sensations without attachment\", \"Observe everything that arises with curiosity\", \"Return to breath as your stable home base\", \"Finish with 3 minutes of breath awareness\", \"End by slowly opening your eyes\"], \"title\": \"Instructions\"}, {\"list\": [\"Develops a complete meditation practice\", \"Builds mental strength and flexibility\", \"Creates deep relaxation and peace\", \"Integrates multiple mindfulness skills\", \"Prepares you for independent practice\"], \"title\": \"Benefits\"}], \"description\": \"Combine breath awareness, body scanning, and present-moment anchoring into one comprehensive practice.\", \"timerMinutes\": 30}','video','https://www.youtube.com/embed/z6X5oEIg6Ak'),(6,2,'Sleep Preparation Breathing','Use extended exhale breathing to activate your body natural relaxation response before sleep.','Breathing',5,10,NULL,1,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Why Extended Exhale Works\", \"content\": \"When your exhale is longer than your inhale, it activates your parasympathetic nervous system - your rest and digest mode. This technique is scientifically proven to reduce heart rate and blood pressure, preparing your body for sleep.\"}, {\"list\": [\"Lie down in bed in your preferred sleeping position\", \"Place one hand on your belly to feel it rise and fall\", \"Breathe in through your nose for a count of 4\", \"Feel your belly expand like a balloon\", \"Exhale slowly through your mouth for a count of 6\", \"Feel your belly gently deflate\", \"Repeat this 4-6 breathing pattern\", \"Let each breath become slower and softer\", \"If your mind wanders, gently return to counting\", \"Continue for the full 5 minutes\"], \"title\": \"Instructions\"}, {\"list\": [\"Activates natural relaxation response quickly\", \"Reduces heart rate and blood pressure\", \"Calms racing thoughts before bed\", \"Helps you fall asleep faster\"], \"title\": \"Benefits\"}], \"description\": \"Use extended exhale breathing to activate your body natural relaxation response before sleep.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/aXItOY0sLRY'),(7,2,'Progressive Muscle Relaxation','Systematically tense and release muscle groups to release physical tension.','Relaxation',10,10,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"How PMR Works\", \"content\": \"Progressive Muscle Relaxation helps you recognize and release tension you may not even realize you are holding. By deliberately tensing and releasing each muscle group, you teach your body what true relaxation feels like.\"}, {\"list\": [\"Lie down comfortably in bed\", \"Take three deep, calming breaths\", \"Start with your feet: curl toes tightly for 5 seconds\", \"Release and notice the relaxation for 10 seconds\", \"Tense your calves and shins, then release\", \"Move to thighs: squeeze tightly, then let go\", \"Tense your buttocks and hips, then release\", \"Clench your stomach muscles, then soften\", \"Make fists with your hands, hold, then release\", \"Tense your arms and shoulders, then drop them\", \"Scrunch your face muscles, then relax completely\", \"End with your whole body tensed, then fully released\", \"Rest and enjoy the deep relaxation\"], \"title\": \"Instructions\"}, {\"list\": [\"Releases deep physical tension\", \"Teaches body awareness and control\", \"Reduces muscle pain and stiffness\", \"Prepares body for restful sleep\"], \"title\": \"Benefits\"}], \"description\": \"Systematically tense and release muscle groups to release physical tension before sleep.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/86HUcX8ZtAk'),(8,2,'Body Scan for Sleep','A gentle, sleep-inducing body scan designed to progressively relax each part of your body.','Body Scan',15,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Sleep-Focused Body Scan\", \"content\": \"This body scan is specifically designed to help you fall asleep. Unlike daytime body scans, this practice encourages drowsiness and uses softer, slower attention that invites sleep.\"}, {\"list\": [\"Lie in your preferred sleeping position\", \"Close your eyes and let them stay closed\", \"Take three slow, deep breaths\", \"Bring gentle awareness to your feet\", \"Imagine warmth and heaviness spreading through them\", \"Let your feet sink into the mattress\", \"Slowly move attention up through your legs\", \"Feel each part becoming heavy and relaxed\", \"Continue through hips, belly, and chest\", \"Notice your breathing becoming slower\", \"Scan through arms, neck, and head\", \"Let your whole body feel heavy and relaxed\", \"If you fall asleep before finishing, that is perfect\"], \"title\": \"Instructions\"}, {\"list\": [\"Guides you naturally into sleep\", \"Releases tension accumulated during the day\", \"Calms anxious or racing thoughts\", \"Improves sleep quality significantly\"], \"title\": \"Benefits\"}], \"description\": \"A gentle, sleep-inducing body scan designed to progressively relax each part of your body.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/aNXKjGFUlMs'),(9,2,'Working with Racing Thoughts','Learn techniques to work with a busy mind at bedtime without fighting or suppressing thoughts.','Meditation',10,10,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Understanding Racing Thoughts\", \"content\": \"Racing thoughts at bedtime are incredibly common. Instead of fighting them, this practice teaches you to change your relationship with thoughts so they lose their power to keep you awake.\"}, {\"list\": [\"Lie down and get comfortable in bed\", \"Close your eyes and notice your thoughts\", \"Do not try to stop or change them\", \"Imagine your thoughts as clouds passing in the sky\", \"Watch each thought appear and then drift away\", \"Label thoughts: planning, worrying, remembering\", \"Return attention to your breath after each thought\", \"Notice the space between thoughts\", \"If thoughts speed up, that is okay - just observe\", \"Keep returning gently to your breath\", \"Let thoughts become background noise\", \"Allow yourself to drift toward sleep\"], \"title\": \"Instructions\"}, {\"list\": [\"Reduces nighttime anxiety and worry\", \"Teaches non-reactive awareness of thoughts\", \"Helps you fall asleep despite mental activity\", \"Breaks the cycle of sleep anxiety\"], \"title\": \"Benefits\"}], \"description\": \"Learn techniques to work with a busy mind at bedtime without fighting or suppressing thoughts.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/86HUcX8ZtAk'),(10,2,'Yoga Nidra for Deep Rest','Experience yogic sleep - a state of conscious deep rest that provides profound relaxation.','Relaxation',35,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"?‍♀️\", \"sections\": [{\"title\": \"What is Yoga Nidra?\", \"content\": \"Yoga Nidra means yogic sleep. It is a state between waking and sleeping where your body is completely relaxed but your mind remains aware. Just 30 minutes of Yoga Nidra can feel as restorative as several hours of sleep.\"}, {\"list\": [\"Lie flat on your back with legs slightly apart\", \"Let your arms rest by your sides, palms up\", \"Close your eyes and commit to staying awake\", \"Set an intention for your practice\", \"Follow the guided awareness through your body\", \"Notice sensations without moving or adjusting\", \"Practice rotation of consciousness through body parts\", \"Remain aware but deeply relaxed\", \"Observe your breath without controlling it\", \"Experience visualizations with your inner eye\", \"Return awareness to your body slowly\", \"When ready, gently wiggle fingers and toes\", \"Roll to your side before sitting up\"], \"title\": \"Instructions\"}, {\"list\": [\"Provides profound physical and mental rest\", \"Reduces chronic fatigue and exhaustion\", \"Heals sleep debt accumulated over time\", \"Accesses deep states of consciousness\", \"Reduces stress and anxiety dramatically\"], \"title\": \"Benefits\"}], \"description\": \"Experience yogic sleep - a state of conscious deep rest that provides profound relaxation.\", \"timerMinutes\": 35}','video','https://www.youtube.com/embed/M0u9GST_j3s'),(11,3,'Observing Anxiety with Curiosity','Learn to observe anxiety symptoms with curiosity rather than fear.','Meditation',5,10,NULL,1,'2025-11-29 00:13:19','{\"icon\": \"?️\", \"sections\": [{\"title\": \"Why Curiosity Helps Anxiety\", \"content\": \"When you meet anxiety with fear, it grows stronger. When you meet it with curious observation, you realize it is just a collection of physical sensations and thoughts that cannot actually harm you.\"}, {\"list\": [\"Sit comfortably and close your eyes\", \"Notice where you feel anxiety in your body\", \"Describe the sensation: tight, fluttery, heavy?\", \"Notice the size and shape of the feeling\", \"Observe it like a scientist studying something interesting\", \"Ask: What does this sensation feel like exactly?\", \"Notice if it changes as you observe it\", \"Breathe into the area where you feel it\", \"Stay curious, not judgmental\", \"Notice thoughts connected to the sensation\", \"Return to observing the physical feeling\"], \"title\": \"Instructions\"}, {\"list\": [\"Reduces fear of anxiety itself\", \"Teaches that anxiety is just a sensation\", \"Breaks the anxiety-about-anxiety cycle\", \"Builds confidence in handling anxious feelings\"], \"title\": \"Benefits\"}], \"description\": \"Learn to observe anxiety symptoms with curiosity rather than fear, changing your relationship with anxious feelings.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/O-6f5wQXSu8'),(12,3,'5-4-3-2-1 Grounding Technique','Use your five senses to anchor yourself in the present moment, interrupting anxiety spirals.','Grounding',5,10,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"How Grounding Stops Anxiety\", \"content\": \"Anxiety happens when your mind is stuck in the future (worrying) or past (regretting). The 5-4-3-2-1 technique brings you back to right now by engaging your senses, which only exist in the present moment.\"}, {\"list\": [\"Sit or stand and look around you\", \"Name 5 things you can SEE in detail\", \"Describe their colors, shapes, and textures\", \"Name 4 things you can TOUCH or FEEL\", \"Notice textures: smooth, rough, warm, cool\", \"Name 3 things you can HEAR\", \"Listen for distant sounds and nearby sounds\", \"Name 2 things you can SMELL\", \"If you cannot smell anything, name favorite smells\", \"Name 1 thing you can TASTE\", \"Or recall your last meal or drink\", \"Take three slow, deep breaths\", \"Notice how you feel more present and grounded\"], \"title\": \"Instructions\"}, {\"list\": [\"Immediately interrupts anxiety spirals\", \"Brings you back to the present moment\", \"Can be done anywhere, anytime discreetly\", \"Works quickly in acute anxiety situations\"], \"title\": \"Benefits\"}], \"description\": \"Use your five senses to anchor yourself in the present moment, interrupting anxiety spirals immediately.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/30VMIEmA114'),(13,3,'Cognitive Defusion Practice','Learn to observe anxious thoughts without getting caught up in their content.','Meditation',10,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"What is Cognitive Defusion?\", \"content\": \"Cognitive defusion means separating yourself from your thoughts. Instead of being fused with the thought (I AM anxious), you observe the thought (I am having the thought that I am anxious). This creates powerful distance.\"}, {\"list\": [\"Sit comfortably and close your eyes\", \"Notice an anxious thought that is present\", \"Say to yourself: I am having the thought that...\", \"Complete the sentence with your anxious thought\", \"Notice the difference this creates\", \"Imagine the thought written on a leaf floating down a stream\", \"Watch it drift away without grabbing it\", \"Label the thought: worrying, planning, judging\", \"Thank your mind for trying to protect you\", \"Return attention to your breath\", \"Practice with several different thoughts\", \"Notice how thoughts lose power when observed\"], \"title\": \"Instructions\"}, {\"list\": [\"Reduces belief in automatic anxious thoughts\", \"Creates distance from overwhelming worries\", \"Teaches that thoughts are not facts\", \"Breaks rumination and thought loops\", \"Builds psychological flexibility\"], \"title\": \"Benefits\"}], \"description\": \"Learn to observe anxious thoughts without getting caught up in their content or believing them automatically.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/thcEuMDWxoI'),(14,3,'Somatic Anxiety Release','Process anxiety through the body using breath, movement, and release techniques.','Body Scan',15,25,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Why Somatic Release Works\", \"content\": \"Anxiety is not just mental - it creates real physical tension and nervous system activation. Somatic release techniques help you discharge this energy through your body rather than trying to think your way out of anxiety.\"}, {\"list\": [\"Stand or sit where you can move freely\", \"Take three deep breaths into your belly\", \"Scan your body for where anxiety lives\", \"Shake out your arms and hands vigorously\", \"Shake your legs and feet to release tension\", \"Make any sound that wants to come out (sigh, groan)\", \"Tense your whole body tight, then release\", \"Repeat the tension-release three times\", \"Place your hands on your heart\", \"Take slow breaths and feel your heartbeat\", \"Imagine breathing directly into tense areas\", \"Continue until you feel energy has moved\", \"End with gentle swaying or rocking motion\"], \"title\": \"Instructions\"}, {\"list\": [\"Releases trapped nervous energy quickly\", \"Discharges physical anxiety symptoms\", \"Works when talk or thought alone does not help\", \"Helps you feel more embodied and grounded\", \"Completes the stress response cycle\"], \"title\": \"Benefits\"}], \"description\": \"Process anxiety through the body using breath, movement, and release techniques that discharge nervous energy.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/aNXKjGFUlMs'),(15,3,'RAIN for Anxiety','Full anxiety management session combining multiple evidence-based techniques.','Meditation',20,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"☔\", \"sections\": [{\"title\": \"The RAIN Technique\", \"content\": \"RAIN is a powerful four-step process developed by mindfulness teacher Michele McDonald and popularized by Tara Brach. It guides you through a complete process of working with difficult emotions like anxiety with wisdom and self-compassion.\"}, {\"list\": [\"Find a quiet place to sit comfortably\", \"RECOGNIZE: What am I experiencing right now?\", \"Name the anxiety and where you feel it\", \"ALLOW: Let it be here without trying to fix it\", \"Say: This anxiety is allowed to be here\", \"INVESTIGATE: Explore the feeling with gentle curiosity\", \"What does this feel like in my body?\", \"What does this part of me need?\", \"What is it believing or afraid of?\", \"NURTURE: Offer yourself compassion and kindness\", \"Place your hand on your heart\", \"Say: May I be kind to myself in this moment\", \"Imagine how you would comfort a good friend\", \"Rest in the awareness that opened up\"], \"title\": \"Instructions\"}, {\"list\": [\"Provides complete process for working with anxiety\", \"Builds self-compassion and emotional wisdom\", \"Transforms relationship with difficult emotions\", \"Teaches skills that work for any strong emotion\", \"Creates lasting change in how you handle anxiety\"], \"title\": \"Benefits\"}], \"description\": \"Use the RAIN technique (Recognize, Allow, Investigate, Nurture) for comprehensive anxiety management.\", \"timerMinutes\": 20}','video','https://www.youtube.com/embed/sz7cpV7ERsM'),(16,4,'Quick Stress Reset','Rapid stress relief technique you can use anywhere, anytime.','Meditation',5,10,NULL,1,'2025-11-29 00:13:19','{\"icon\": \"⚡\", \"sections\": [{\"title\": \"Emergency Stress Relief\", \"content\": \"This quick technique combines breathing, grounding, and mindful awareness to rapidly shift your nervous system out of fight-or-flight mode. Perfect for using between meetings, before presentations, or whenever stress spikes.\"}, {\"list\": [\"Stop what you are doing for just 5 minutes\", \"Place your feet flat on the floor\", \"Feel the solid ground beneath you\", \"Take three deep belly breaths\", \"Inhale for 4, hold for 4, exhale for 6\", \"Scan your body for tension hotspots\", \"Consciously relax your jaw and shoulders\", \"Roll your shoulders backward three times\", \"Shake out your hands vigorously\", \"Take two more deep breaths\", \"Notice how your body feels now versus before\"], \"title\": \"Instructions\"}, {\"list\": [\"Works quickly in acute stress situations\", \"Can be done discreetly anywhere\", \"Interrupts stress response immediately\", \"Helps you think clearly again\"], \"title\": \"Benefits\"}], \"description\": \"Rapid stress relief technique you can use anywhere, anytime to reset your nervous system.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/MR57rug8NsM'),(17,4,'Box Breathing for Calm','Navy SEAL technique for managing stress under pressure.','Breathing',5,10,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Why Navy SEALs Use This\", \"content\": \"Box breathing, also called four-square breathing, is used by Navy SEALs to stay calm in extreme situations. The even counts activate your parasympathetic nervous system and give your mind something to focus on.\"}, {\"list\": [\"Sit upright with your back supported\", \"Exhale completely to empty your lungs\", \"Inhale through your nose for a count of 4\", \"Hold your breath for a count of 4\", \"Exhale through your mouth for a count of 4\", \"Hold your breath (empty) for a count of 4\", \"This completes one box\", \"Repeat the cycle for 5 minutes\", \"If 4 seconds feels too long, use 3 seconds\", \"Keep the counts equal for all four sides\", \"Focus completely on the counting\", \"End with a few natural breaths\"], \"title\": \"Instructions\"}, {\"list\": [\"Calms fight-or-flight response quickly\", \"Improves focus under pressure\", \"Reduces blood pressure and heart rate\", \"Gives mind something neutral to focus on\"], \"title\": \"Benefits\"}], \"description\": \"Master the Navy SEAL technique for managing stress under pressure through controlled breathing.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/tEmt1Znux58'),(18,4,'The Relaxation Response','Develop your ability to consciously activate deep relaxation.','Meditation',15,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Understanding Somatic Stress\", \"content\": \"Stress does not just live in your mind - it gets trapped in your muscles, fascia, and nervous system. Somatic release techniques help you discharge this accumulated tension through gentle movement and breathwork.\"}, {\"list\": [\"Stand with feet hip-width apart\", \"Close your eyes and scan for tension\", \"Notice where stress lives in your body\", \"Begin with gentle neck rolls\", \"Roll shoulders backward slowly 5 times\", \"Shake out your arms and hands\", \"Bounce gently on your feet\", \"Sway side to side like seaweed\", \"Make fists and release 5 times\", \"Take deep breaths into tense areas\", \"Allow any sounds or sighs to emerge\", \"End standing still, noticing changes\"], \"title\": \"Instructions\"}, {\"list\": [\"Releases stored physical tension\", \"Completes interrupted stress cycles\", \"Restores natural energy flow\", \"Helps when talk therapy is not enough\"], \"title\": \"Benefits\"}], \"description\": \"Release stress stored in your body through mindful movement and breath work.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/wfDTp2GogaQ'),(19,4,'Reframing Stressful Thoughts','Change your relationship with stressful thoughts through mindful awareness.','Meditation',15,25,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?️\", \"sections\": [{\"title\": \"What is Resilience?\", \"content\": \"Resilience is not about avoiding stress - it is about developing the inner resources to handle stress when it comes. This practice builds your psychological strength and flexibility.\"}, {\"list\": [\"Sit comfortably with eyes closed\", \"Recall a time you overcame difficulty\", \"Notice the strength you demonstrated\", \"Feel that strength in your body now\", \"Breathe into this feeling of capability\", \"Acknowledge your inherent resilience\", \"Think of current challenges you face\", \"Imagine bringing your strength to them\", \"Visualize yourself handling them well\", \"Notice resources and support available\", \"Rest in knowing you can handle what comes\", \"Take three empowering breaths\"], \"title\": \"Instructions\"}, {\"list\": [\"Builds confidence in handling stress\", \"Connects you to inner strength\", \"Reduces fear of future challenges\", \"Develops growth mindset\"], \"title\": \"Benefits\"}], \"description\": \"Develop your capacity to bounce back from stress through inner strength practices.\", \"timerMinutes\": 20}','video','https://www.youtube.com/embed/15q-N-_kkrU'),(20,4,'Building Stress Resilience','Comprehensive stress resilience practice combining multiple techniques.','Meditation',25,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Complete Stress Reset\", \"content\": \"This comprehensive practice addresses stress on all levels - physical, mental, and emotional. It is perfect for when you need a complete system reboot after an overwhelming day.\"}, {\"list\": [\"Lie down or recline comfortably\", \"Start with 5 minutes of box breathing\", \"Scan your body for stress hotspots\", \"Breathe deeply into each tense area\", \"Practice progressive muscle relaxation\", \"Tense and release each muscle group\", \"Return to natural breathing\", \"Imagine stress draining from your body\", \"Visualize it flowing into the earth\", \"Notice your body becoming lighter\", \"Set an intention for how you want to feel\", \"Rest in stillness for final 5 minutes\"], \"title\": \"Instructions\"}, {\"list\": [\"Provides complete stress relief\", \"Resets your entire nervous system\", \"Restores energy and clarity\", \"Prepares you to engage with life again\"], \"title\": \"Benefits\"}], \"description\": \"Comprehensive stress relief combining breathwork, body awareness, and mental reset.\", \"timerMinutes\": 25}','video','https://www.youtube.com/embed/Jyy0ra2WcQQ'),(21,5,'Introduction to Self-Compassion','Learn the three components of self-compassion: self-kindness, common humanity, and mindfulness.','Meditation',5,10,NULL,1,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Self-Compassion in Hard Moments\", \"content\": \"This brief practice uses Kristin Neff\'s three components of self-compassion: mindfulness, common humanity, and self-kindness. Perfect for when you are struggling or being hard on yourself.\"}, {\"list\": [\"Pause and acknowledge: This is a moment of suffering\", \"Place your hand on your heart\", \"Feel the warmth and pressure of your hand\", \"Say: Suffering is part of life\", \"Recognize you are not alone in struggling\", \"Everyone experiences difficulty\", \"Say: May I be kind to myself\", \"Ask: What do I need right now?\", \"Offer yourself what you need\", \"Take three compassionate breaths\"], \"title\": \"Instructions\"}, {\"list\": [\"Interrupts self-criticism quickly\", \"Activates self-soothing system\", \"Reduces isolation in suffering\", \"Provides comfort when needed most\"], \"title\": \"Benefits\"}], \"description\": \"Quick practice for moments of difficulty or self-judgment to activate self-compassion.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/O-6f5wQXSu8'),(22,5,'Self-Compassion Break','Quick practice for moments of difficulty or self-judgment.','Meditation',10,10,NULL,2,'2025-11-29 00:13:19',NULL,'video','https://www.youtube.com/embed/11U0h0DPu7k'),(23,5,'Affectionate Breathing','Breathe kindness and warmth into yourself.','Breathing',15,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"❤️\", \"sections\": [{\"title\": \"Metta for Yourself\", \"content\": \"Loving-kindness (metta) meditation traditionally begins with yourself. You cannot genuinely wish others well if you harbor resentment or criticism toward yourself. This practice builds authentic self-love.\"}, {\"list\": [\"Sit comfortably and close your eyes\", \"Bring to mind an image of yourself\", \"See yourself as worthy of love\", \"Silently repeat: May I be happy\", \"May I be healthy\", \"May I be safe\", \"May I live with ease\", \"Feel the meaning behind each phrase\", \"Notice resistance or difficulty - this is normal\", \"Keep returning to the phrases\", \"Let warmth build in your heart\", \"Rest in the feeling of self-love\"], \"title\": \"Instructions\"}, {\"list\": [\"Builds genuine self-love over time\", \"Reduces self-criticism and judgment\", \"Improves relationship with yourself\", \"Creates foundation for loving others\"], \"title\": \"Benefits\"}], \"description\": \"Traditional metta meditation directed toward yourself to cultivate genuine self-love.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/gz4G31LGyog'),(24,5,'Loving-Kindness for Self','Traditional metta (loving-kindness) meditation directed toward yourself.','Meditation',15,25,NULL,4,'2025-11-29 00:13:19',NULL,'video','https://www.youtube.com/embed/sz7cpV7ERsM'),(25,5,'Compassionate Friend Visualization','Meet your inner compassionate friend who offers unconditional support.','Meditation',25,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"✨\", \"sections\": [{\"title\": \"Embodied Self-Love\", \"content\": \"This practice goes beyond mental affirmations to help you feel self-love in your body and nervous system. Repeated practice rewires your brain to default to self-kindness.\"}, {\"list\": [\"Lie down or sit very comfortably\", \"Place both hands on your heart\", \"Feel your heartbeat and warmth\", \"Imagine breathing love into your heart\", \"Repeat: I am worthy of love and belonging\", \"I am enough exactly as I am\", \"I treat myself with kindness\", \"Feel each affirmation in your body\", \"Notice where love shows up physically\", \"Imagine filling your whole body with warmth\", \"Visualize yourself radiating love\", \"Rest in this feeling for several minutes\"], \"title\": \"Instructions\"}, {\"list\": [\"Rewires brain for self-compassion\", \"Creates felt sense of worthiness\", \"Heals old patterns of self-criticism\", \"Builds unshakeable self-love\"], \"title\": \"Benefits\"}], \"description\": \"Deep practice combining visualization, affirmations, and embodied self-love.\", \"timerMinutes\": 25}','video','https://www.youtube.com/embed/z6X5oEIg6Ak'),(26,6,'Morning Wake-Up Breathing','Start your day with conscious breathing before reaching for your phone.','Breathing',5,10,NULL,1,'2025-11-29 00:13:19',NULL,'video','https://www.youtube.com/embed/cEqZthCaMpo'),(27,6,'Gratitude Meditation','Cultivate appreciation for your life through structured gratitude practice.','Meditation',10,10,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Starting Your Day Mindfully\", \"content\": \"Instead of jumping out of bed into doing mode, this practice helps you transition gently into wakefulness. You will start your day feeling grounded and present rather than reactive and stressed.\"}, {\"list\": [\"Before getting out of bed, lie still\", \"Notice how your body feels this morning\", \"Wiggle your toes and fingers gently\", \"Scan from feet up through your body\", \"Notice areas of stiffness or ease\", \"Take three deep morning breaths\", \"Stretch arms overhead with a yawn\", \"Roll to one side and pause\", \"Sit up slowly and feel your spine lengthen\", \"Set a simple intention for your day\", \"Take one more grounding breath\"], \"title\": \"Instructions\"}, {\"list\": [\"Starts day with mindful awareness\", \"Reduces morning anxiety and rush\", \"Helps you feel more present all day\", \"Sets positive tone from the start\"], \"title\": \"Benefits\"}], \"description\": \"Gentle morning body scan to wake up mindfully and set positive tone for your day.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/11U0h0DPu7k'),(28,6,'Setting Daily Intentions','Clarify your values and set meaningful intentions for the day ahead.','Meditation',10,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"☕\", \"sections\": [{\"title\": \"Mindful Drinking Practice\", \"content\": \"Most people drink their morning coffee or tea while scrolling or planning. This practice turns an everyday activity into a rich sensory experience that anchors you in the present moment.\"}, {\"list\": [\"Prepare your beverage with full attention\", \"Notice the sounds of water and brewing\", \"Hold the warm cup in both hands\", \"Feel the warmth spreading to your palms\", \"Bring the cup close and smell deeply\", \"Notice all the subtle aromas\", \"Take your first sip very slowly\", \"Notice temperature, texture, taste\", \"Feel the liquid traveling down\", \"Continue drinking with full presence\", \"Put phone away during this time\"], \"title\": \"Instructions\"}, {\"list\": [\"Turns routine into ritual\", \"Practices present-moment awareness\", \"Enhances enjoyment of simple pleasures\", \"Creates pause before busy day starts\"], \"title\": \"Benefits\"}], \"description\": \"Transform your morning beverage into a mindfulness practice using all five senses.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/30VMIEmA114'),(29,6,'Energizing Morning Breathwork','Use invigorating breathing techniques to wake up your body and mind.','Breathing',15,25,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Setting Intentional Direction\", \"content\": \"Intentions are different from goals. Goals are about doing; intentions are about being. This practice helps you decide who you want to be today, regardless of what happens.\"}, {\"list\": [\"Sit comfortably with eyes closed\", \"Take three grounding breaths\", \"Ask: What matters most to me?\", \"Consider your core values\", \"Ask: Who do I want to be today?\", \"Patient? Kind? Present? Creative?\", \"Choose one or two qualities to embody\", \"Visualize moving through your day with these qualities\", \"See yourself responding, not reacting\", \"Notice how this would feel\", \"State your intention clearly\", \"Take three breaths to anchor it\"], \"title\": \"Instructions\"}, {\"list\": [\"Aligns day with your values\", \"Provides compass when challenges arise\", \"Reduces reactive living\", \"Increases sense of purpose\"], \"title\": \"Benefits\"}], \"description\": \"Clarify your values and set meaningful intentions for the day ahead with purpose.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/aNXKjGFUlMs'),(30,6,'Complete Morning Ritual','Full morning practice combining breath, gratitude, body awareness, and intention.','Meditation',25,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"⚡\", \"sections\": [{\"title\": \"Full Morning Activation\", \"content\": \"This comprehensive morning ritual combines physical activation, mental clarity, and emotional preparation. You will feel alert, grounded, and ready to meet your day with energy and presence.\"}, {\"list\": [\"Start standing with feet hip-width apart\", \"Do 10 gentle neck rolls each direction\", \"Roll shoulders backward 10 times\", \"Do 5-10 jumping jacks or march in place\", \"Transition to energizing breath of fire\", \"30 quick belly pumps through nose\", \"Stand in mountain pose for 3 breaths\", \"Reach arms overhead and stretch tall\", \"Fold forward and hang for 5 breaths\", \"Slowly roll up to standing\", \"Set your intention for the day\", \"Place hand on heart and commit to it\"], \"title\": \"Instructions\"}, {\"list\": [\"Wakes up body and mind fully\", \"Increases energy and alertness\", \"Combines movement and mindfulness\", \"Prepares you physically and mentally\", \"Creates sustainable morning routine\"], \"title\": \"Benefits\"}], \"description\": \"Dynamic morning practice combining breathwork, movement, and intention to energize your day.\", \"timerMinutes\": 20}','video','https://www.youtube.com/embed/sz7cpV7ERsM'),(31,7,'Recognizing Your Emotions','Develop the skill of identifying and naming emotions as they arise.','Meditation',5,10,NULL,1,'2025-11-29 00:13:19',NULL,'video','https://www.youtube.com/embed/92i5m3tV5XY'),(32,7,'The STOP Technique','Learn to pause between stimulus and response to choose your reaction.','Grounding',5,10,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Why Emotion Check-Ins Matter\", \"content\": \"Most people go through life unaware of their emotions until they become overwhelming. Regular check-ins help you catch emotions early when they are easier to work with.\"}, {\"list\": [\"Sit quietly and close your eyes\", \"Take three settling breaths\", \"Ask: What am I feeling right now?\", \"Wait for the answer to emerge\", \"Name the emotion: sad, anxious, angry, joyful\", \"Where do I feel this in my body?\", \"Notice physical sensations connected to it\", \"How strong is this feeling? 1-10?\", \"Just observe without trying to change it\", \"Ask: What does this emotion need?\", \"Listen with compassion to the answer\"], \"title\": \"Instructions\"}, {\"list\": [\"Builds emotional awareness and literacy\", \"Catches difficult emotions early\", \"Prevents emotional overwhelm\", \"Improves emotional intelligence\"], \"title\": \"Benefits\"}], \"description\": \"Regular practice to identify, name, and locate emotions in your body.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/thcEuMDWxoI'),(33,7,'Working with Anger','Mindfully work with anger without suppressing it or acting it out.','Meditation',15,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"The Middle Way with Emotions\", \"content\": \"We often either suppress emotions (push them down) or express them reactively (act them out). This practice teaches the middle way: being present with emotions until they naturally transform.\"}, {\"list\": [\"Identify a difficult emotion you are feeling\", \"Find a comfortable seated position\", \"Locate the emotion in your body\", \"Notice its size, shape, temperature, texture\", \"Breathe gently toward this area\", \"Say: I see you. You are allowed to be here\", \"Stay present with the sensation\", \"Notice if it changes as you observe it\", \"Resist urges to fix, change, or escape it\", \"Ask: What is this emotion trying to tell me?\", \"Listen without judgment\", \"Offer yourself compassion for struggling\"], \"title\": \"Instructions\"}, {\"list\": [\"Builds capacity to handle difficult feelings\", \"Reduces emotional reactivity significantly\", \"Teaches emotions pass when not resisted\", \"Develops emotional wisdom\"], \"title\": \"Benefits\"}], \"description\": \"Learn to be with difficult emotions without suppressing or acting them out.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/wfDTp2GogaQ'),(34,7,'Healing Sadness and Grief','Hold difficult emotions with compassion rather than pushing them away.','Meditation',15,25,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Releasing What You Have Been Holding\", \"content\": \"Sometimes emotions get stuck in our bodies because we never fully felt them. This practice creates a safe container to finally let yourself feel and release what you have been carrying.\"}, {\"list\": [\"Lie down or sit comfortably\", \"Place your hands on your heart\", \"Create a sense of safety and support\", \"Bring to mind something you need to release\", \"Notice where you feel it in your body\", \"Breathe deeply into that area\", \"Allow whatever feelings arise\", \"Tears, anger, grief are all welcome\", \"Keep breathing and staying present\", \"Imagine the emotion flowing out with exhales\", \"Continue until you feel a natural shift\", \"End with self-compassion and rest\"], \"title\": \"Instructions\"}, {\"list\": [\"Releases long-held emotional tension\", \"Completes unfinished emotional processes\", \"Creates space for new experiences\", \"Brings relief and lightness\", \"Heals old emotional wounds\"], \"title\": \"Benefits\"}], \"description\": \"Safe practice for releasing stuck emotions through awareness, breath, and compassionate presence.\", \"timerMinutes\": 20}','video','https://www.youtube.com/embed/sz7cpV7ERsM'),(35,7,'Emotional Balance Practice','Comprehensive practice for developing emotional regulation capacity.','Meditation',20,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Emotional Resilience\", \"content\": \"Emotional resilience is not about staying positive or never feeling bad. It is about developing the capacity to ride the waves of all emotions with grace, knowing you can handle whatever arises.\"}, {\"list\": [\"Settle into a comfortable position\", \"Acknowledge your emotional capacity\", \"Recall a time you handled difficulty well\", \"What inner resources did you access?\", \"Notice the strength already within you\", \"Practice expanding your window of tolerance\", \"Sit with mild discomfort without reacting\", \"Notice you can handle more than you think\", \"Visualize yourself weathering emotional storms\", \"See yourself remaining grounded\", \"Recognize emotions as temporary weather\", \"You are the sky, not the weather\", \"Rest in this expansive awareness\"], \"title\": \"Instructions\"}, {\"list\": [\"Expands emotional capacity significantly\", \"Reduces fear of difficult emotions\", \"Builds confidence in emotional strength\", \"Creates lasting emotional flexibility\", \"Helps you stay steady through life storms\"], \"title\": \"Benefits\"}], \"description\": \"Comprehensive practice developing capacity to navigate the full range of human emotions.\", \"timerMinutes\": 25}','video','https://www.youtube.com/embed/M0u9GST_j3s'),(36,8,'Three-Part Breath','Learn to breathe fully into belly, ribs, and chest.','Breathing',5,10,NULL,1,'2025-11-29 00:13:19',NULL,'video','https://www.youtube.com/embed/DbDoBzGY3vo'),(37,8,'Extended Exhale Calming Breath','Activate your relaxation response through extended exhales.','Breathing',5,10,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"⬜\", \"sections\": [{\"title\": \"Four-Square Breathing\", \"content\": \"Box breathing creates balance by making all four phases of breathing equal. The structure gives your mind something to focus on while the even rhythm calms your nervous system.\"}, {\"list\": [\"Sit with spine straight and supported\", \"Empty your lungs completely\", \"Inhale through nose for count of 4\", \"Hold breath in for count of 4\", \"Exhale through mouth for count of 4\", \"Hold breath out for count of 4\", \"This is one complete box\", \"Visualize drawing a square\", \"Continue for 10 complete minutes\", \"If you feel dizzy, breathe normally\", \"Gradually return to natural breathing\"], \"title\": \"Instructions\"}, {\"list\": [\"Regulates nervous system quickly\", \"Improves concentration and focus\", \"Reduces anxiety and stress\", \"Balances your energy levels\"], \"title\": \"Benefits\"}], \"description\": \"Master controlled breathing rhythm to calm nervous system and improve focus.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/86HUcX8ZtAk'),(38,8,'Box Breathing and 4-7-8 Technique','Master two powerful breathing patterns for calm and sleep.','Breathing',15,25,NULL,3,'2025-11-29 00:13:19',NULL,'video','https://www.youtube.com/embed/gz4G31LGyog'),(39,8,'Alternate Nostril Breathing','Balance your nervous system through yogic breathing.','Breathing',15,25,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?‍♂️\", \"sections\": [{\"title\": \"Nadi Shodhana (Channel Purification)\", \"content\": \"This ancient pranayama technique balances the ida and pingala energy channels, creating mental clarity and emotional balance. It is one of the most effective breathing practices for stress.\"}, {\"list\": [\"Sit comfortably with spine erect\", \"Use right hand for nostril control\", \"Rest left hand on your knee\", \"Close right nostril with right thumb\", \"Inhale slowly through left nostril\", \"Close left nostril with ring finger\", \"Release thumb and exhale through right\", \"Inhale through right nostril\", \"Close right, exhale through left\", \"This is one complete round\", \"Continue for 10-15 rounds\", \"End exhaling through left nostril\"], \"title\": \"Instructions\"}, {\"list\": [\"Balances left and right brain\", \"Calms nervous system deeply\", \"Improves mental clarity and focus\", \"Reduces anxiety and tension\", \"Prepares mind for meditation\"], \"title\": \"Benefits\"}], \"description\": \"Traditional yogic breathing to balance left and right brain hemispheres and calm the mind.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/wfDTp2GogaQ'),(40,8,'Advanced Breathing Integration','Comprehensive session combining multiple breathing techniques.','Breathing',30,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"?️\", \"sections\": [{\"title\": \"Integrated Pranayama Practice\", \"content\": \"This advanced session combines several breathing techniques to create a complete pranayama practice. Work with your breath in progressively deeper ways to access expanded states of consciousness.\"}, {\"list\": [\"Begin with 5 minutes of natural breathing\", \"Observe breath without controlling it\", \"Practice ujjayi breath (ocean breath) for 5 minutes\", \"Slightly constrict back of throat\", \"Transition to bhastrika (bellows breath)\", \"30 rapid belly pumps, then hold breath\", \"Repeat 3 rounds with rest between\", \"Return to alternate nostril breathing\", \"10 slow rounds balancing both sides\", \"Finish with retention practice\", \"Inhale fully, hold comfortably, exhale slowly\", \"End with several minutes natural breathing\"], \"title\": \"Instructions\"}, {\"list\": [\"Expands lung capacity significantly\", \"Energizes while also calming\", \"Accesses deeper states of awareness\", \"Purifies energy channels\", \"Prepares for advanced meditation\"], \"title\": \"Benefits\"}], \"description\": \"Comprehensive breathwork session combining multiple advanced techniques.\", \"timerMinutes\": 25}','video','https://www.youtube.com/embed/z6X5oEIg6Ak'),(41,9,'Quick Sensory Grounding','Use your senses to anchor in the present moment when feeling ungrounded.','Grounding',5,10,NULL,1,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Rapid Body Check-In\", \"content\": \"A quick scan through your body to reconnect with physical sensations. Perfect for when you feel disconnected, anxious, or too much in your head.\"}, {\"list\": [\"Sit or stand with feet on ground\", \"Close eyes or lower gaze\", \"Notice sensations in your feet\", \"Feel contact with floor or shoes\", \"Quickly scan up through legs\", \"Notice belly, chest, and back\", \"Feel arms and hands\", \"Notice head and face\", \"Take three deep breaths\", \"Feel your whole body at once\"], \"title\": \"Instructions\"}, {\"list\": [\"Brings you out of your head\", \"Grounds you in present moment\", \"Reduces anxiety quickly\", \"Reconnects mind and body\"], \"title\": \"Benefits\"}], \"description\": \"Quick body awareness check-in to notice sensations and ground in present moment.\", \"timerMinutes\": 5}','video','https://www.youtube.com/embed/inpok4MKVLM'),(42,9,'Basic Body Scan','Foundational body scan practice for developing interoceptive awareness.','Body Scan',10,10,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"⚓\", \"sections\": [{\"title\": \"Finding Your Ground\", \"content\": \"Grounding techniques help when you feel spacey, anxious, or disconnected. This practice uses visualization and body awareness to create a felt sense of stability and safety.\"}, {\"list\": [\"Sit with feet flat on floor\", \"Feel the solid earth beneath you\", \"Notice weight of your body\", \"Imagine roots growing from your feet\", \"Extending deep into the earth\", \"Feel yourself anchored and stable\", \"Breathe down into your belly\", \"Feel gravity holding you\", \"Notice you are safe and supported\", \"Stay present with body sensations\", \"Let earth energy rise through you\"], \"title\": \"Instructions\"}, {\"list\": [\"Creates felt sense of safety\", \"Reduces feeling of floating or dissociation\", \"Anchors you in present moment\", \"Helps with anxiety and panic\"], \"title\": \"Benefits\"}], \"description\": \"Establish strong connection to earth and body when feeling ungrounded or anxious.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/thcEuMDWxoI'),(43,9,'Interoceptive Awareness Practice','Deepen your ability to sense internal body states and sensations.','Body Scan',15,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Developing Interoception\", \"content\": \"Interoception is your ability to sense what is happening inside your body. Developing this awareness helps you recognize emotions early, notice needs, and stay regulated.\"}, {\"list\": [\"Lie down on your back comfortably\", \"Close eyes and breathe naturally\", \"Notice your heartbeat - where do you feel it?\", \"Sense temperature variations in your body\", \"Notice areas of tension or ease\", \"Feel subtle movement of your breathing\", \"Sense energy or tingling anywhere\", \"Notice sensations you normally ignore\", \"Observe without judging or fixing\", \"Stay curious like a scientist\", \"Notice how sensations change\", \"Rest in expanded body awareness\"], \"title\": \"Instructions\"}, {\"list\": [\"Develops somatic intelligence\", \"Helps recognize emotions in body\", \"Improves self-regulation capacity\", \"Deepens mind-body connection\", \"Supports trauma healing\"], \"title\": \"Benefits\"}], \"description\": \"Deepen interoceptive awareness by exploring subtle body sensations systematically.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/aNXKjGFUlMs'),(44,9,'Walking Meditation','Practice mindfulness through slow, deliberate walking.','Meditation',20,25,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Working with Energy Centers\", \"content\": \"Chakras are energy centers in the body according to yogic philosophy. This practice helps balance and harmonize your energy system, creating overall wellbeing.\"}, {\"list\": [\"Sit comfortably with straight spine\", \"Begin at root chakra (base of spine)\", \"Visualize red glowing light\", \"Move to sacral chakra (below navel) - orange\", \"Solar plexus (upper belly) - yellow\", \"Heart center (chest) - green\", \"Throat chakra - blue\", \"Third eye (between eyebrows) - indigo\", \"Crown (top of head) - violet\", \"Spend 2 minutes with each center\", \"Breathe into each and feel it activate\", \"End feeling all chakras aligned\"], \"title\": \"Instructions\"}, {\"list\": [\"Balances energy system\", \"Clears blocked energy\", \"Promotes overall wellbeing\", \"Deepens spiritual awareness\"], \"title\": \"Benefits\"}], \"description\": \"Balance your energy centers through visualization and breathwork.\", \"timerMinutes\": 20}','video','https://www.youtube.com/embed/15q-N-_kkrU'),(45,9,'Full Body Awareness Meditation','Comprehensive practice cultivating deep body-mind connection.','Body Scan',25,50,NULL,5,'2025-11-29 00:13:19',NULL,'video','https://www.youtube.com/embed/Jyy0ra2WcQQ'),(46,10,'Creating Inner Safety','Establish a felt sense of safety in your body through gentle awareness.','Meditation',10,10,NULL,1,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"The Power of Visualization\", \"content\": \"Research shows visualization activates the same brain regions as actual experience. This practice harnesses your mind\'s healing power to support physical and emotional recovery.\"}, {\"list\": [\"Lie down or recline comfortably\", \"Close eyes and breathe slowly\", \"Imagine healing light above you\", \"See it as golden, warm, and loving\", \"With each inhale, draw it into your body\", \"Let it flow to areas needing healing\", \"See it dissolving pain and tension\", \"Feel warmth spreading through you\", \"Imagine cells being nourished\", \"Trust in your body\'s wisdom to heal\", \"Rest in this healing energy\"], \"title\": \"Instructions\"}, {\"list\": [\"Activates natural healing response\", \"Reduces pain and inflammation\", \"Supports immune function\", \"Creates hope and positive expectations\"], \"title\": \"Benefits\"}], \"description\": \"Use guided imagery to activate your body natural healing processes.\", \"timerMinutes\": 10}','video','https://www.youtube.com/embed/11U0h0DPu7k'),(47,10,'Compassionate Awareness','Hold difficult experiences with gentle, compassionate awareness.','Meditation',15,25,NULL,2,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Meeting Your Inner Child\", \"content\": \"Your inner child holds your earliest wounds and needs. This practice creates healing by offering your younger self the love and protection they needed but may not have received.\"}, {\"list\": [\"Sit comfortably with eyes closed\", \"Take several grounding breaths\", \"Imagine yourself as a young child\", \"See yourself at a specific age\", \"Notice what this child is feeling\", \"What did they need but did not get?\", \"Step toward them with love\", \"Tell them: I see you. You matter.\", \"You are safe now. I am here.\", \"Imagine hugging this young you\", \"Give them what they needed\", \"Promise to keep coming back\"], \"title\": \"Instructions\"}, {\"list\": [\"Heals childhood wounds\", \"Reduces triggers from past\", \"Creates internal sense of safety\", \"Builds self-compassion deeply\", \"Transforms self-relationship\"], \"title\": \"Benefits\"}], \"description\": \"Connect with and heal your inner child through compassionate awareness.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/gz4G31LGyog'),(48,10,'Working with Grief','Mindfully process loss and grief with self-compassion.','Meditation',15,25,NULL,3,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Healing Emotional Wounds\", \"content\": \"Emotional wounds need the same care as physical wounds. This practice creates a safe space to feel, process, and heal old emotional pain you have been carrying.\"}, {\"list\": [\"Create a safe, comfortable space\", \"Place hands on your heart\", \"Bring to mind emotional pain you carry\", \"Do not try to fix or understand it yet\", \"Just acknowledge: This hurt is real\", \"Notice where you feel it in body\", \"Breathe compassion toward this pain\", \"Say: May I heal from this\", \"Imagine breathing light into the hurt\", \"Let yourself feel what needs to be felt\", \"Tears are welcome and healing\", \"End with gratitude for your courage\"], \"title\": \"Instructions\"}, {\"list\": [\"Processes unresolved emotional pain\", \"Releases what you have been carrying\", \"Creates space for new experiences\", \"Builds emotional resilience\", \"Supports deep healing\"], \"title\": \"Benefits\"}], \"description\": \"Process and heal emotional wounds through gentle awareness and self-compassion.\", \"timerMinutes\": 15}','video','https://www.youtube.com/embed/wfDTp2GogaQ'),(49,10,'Trauma-Sensitive Body Scan','Gentle body awareness practice adapted for trauma recovery.','Body Scan',20,25,NULL,4,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Body-Mind Healing\", \"content\": \"Your mind and body are not separate. This practice uses the mind-body connection to support physical healing, reduce pain, and enhance recovery from illness or injury.\"}, {\"list\": [\"Lie down in a comfortable position\", \"Scan body for areas of pain or illness\", \"Bring gentle awareness to these areas\", \"Breathe slowly and deeply\", \"Imagine healing light flowing to that area\", \"See your immune cells working\", \"Visualize inflammation reducing\", \"Feel tissues repairing and healing\", \"Send love and gratitude to your body\", \"Thank it for working to heal\", \"Trust in your body\'s wisdom\", \"Rest deeply in healing awareness\"], \"title\": \"Instructions\"}, {\"list\": [\"Supports physical healing processes\", \"Reduces pain and discomfort\", \"Enhances immune function\", \"Creates positive healing environment\", \"Improves mind-body cooperation\"], \"title\": \"Benefits\"}], \"description\": \"Support your body healing through breathwork, visualization, and loving awareness.\", \"timerMinutes\": 20}','video','https://www.youtube.com/embed/sz7cpV7ERsM'),(50,10,'Deep Healing Integration','Comprehensive healing practice integrating self-compassion, breath, and body awareness.','Meditation',30,50,NULL,5,'2025-11-29 00:13:19','{\"icon\": \"?\", \"sections\": [{\"title\": \"Complete Healing Integration\", \"content\": \"This comprehensive practice addresses healing on all levels - physical, emotional, mental, and spiritual. It creates deep transformation by working with your whole being.\"}, {\"list\": [\"Create sacred space for your practice\", \"Lie down or sit very comfortably\", \"Begin with 5 minutes grounding in body\", \"Acknowledge all that needs healing\", \"Physical pain, emotional wounds, old stories\", \"Welcome it all with compassion\", \"Visualize healing light entering your crown\", \"Let it flow through your entire being\", \"Healing body, heart, and mind\", \"Release what no longer serves you\", \"Call in what supports your healing\", \"Rest in wholeness and completeness\", \"Know that healing is always possible\", \"End with gratitude for your journey\"], \"title\": \"Instructions\"}, {\"list\": [\"Integrates healing on all levels\", \"Transforms at deepest levels\", \"Releases old patterns completely\", \"Creates profound inner peace\", \"Supports ongoing healing journey\", \"Reconnects you with wholeness\"], \"title\": \"Benefits\"}], \"description\": \"Comprehensive healing meditation integrating physical, emotional, and spiritual dimensions.\", \"timerMinutes\": 30}','video','https://www.youtube.com/embed/z6X5oEIg6Ak');
